    public static function doInsert($values, PropelPDO $con = null)
    {
        if ($con === null) {
            $con = Propel::getConnection(ClienteContenidoPeer::DATABASE_NAME, Propel::CONNECTION_WRITE);
        }

        if ($values instanceof Criteria) {
            $criteria = clone $values; // rename for clarity
        } else {
            $criteria = $values->buildCriteria(); // build Criteria from ClienteContenido object
        }

        if ($criteria->containsKey(ClienteContenidoPeer::CLIENTE_CONTENIDO_ID) && $criteria->keyContainsValue(ClienteContenidoPeer::CLIENTE_CONTENIDO_ID) ) {
            throw new PropelException('Cannot insert a value for auto-increment primary key ('.ClienteContenidoPeer::CLIENTE_CONTENIDO_ID.')');
        }

        // remove pkey col since this table uses auto-increment and passing a null value for it is not valid
        $criteria->remove(ClienteContenidoPeer::CLIENTE_CONTENIDO_ID);


        // Set the correct dbName
        $criteria->setDbName(ClienteContenidoPeer::DATABASE_NAME);

        try {
            // use transaction because $criteria could contain info
            // for more than one table (I guess, conceivably)
            $con->beginTransaction();
            $pk = BasePeer::doInsert($criteria, $con);
            $con->commit();
        } catch (Exception $e) {
            $con->rollBack();
            throw $e;
        }

        return $pk;
    }

