            $con->beginTransaction();
            $affectedRows += BasePeer::doDeleteAll(ClienteContenidoPeer::TABLE_NAME, $con, ClienteContenidoPeer::DATABASE_NAME);
            // Because this db requires some delete cascade/set null emulation, we have to
            // clear the cached instance *after* the emulation has happened (since
            // instances get re-added by the select statement contained therein).
            ClienteContenidoPeer::clearInstancePool();
            ClienteContenidoPeer::clearRelatedInstancePool();
            $con->commit();

            return $affectedRows;
        } catch (Exception $e) {
            $con->rollBack();
