     * @param      PropelPDO $con the connection to use
     * @return ClienteContenido
     */
    public static function retrieveByPK($pk, PropelPDO $con = null)
    {

        if (null !== ($obj = ClienteContenidoPeer::getInstanceFromPool((string) $pk))) {
            return $obj;
        }

        if ($con === null) {
            $con = Propel::getConnection(ClienteContenidoPeer::DATABASE_NAME, Propel::CONNECTION_READ);
        }

        $criteria = new Criteria(ClienteContenidoPeer::DATABASE_NAME);
        $criteria->add(ClienteContenidoPeer::CLIENTE_CONTENIDO_ID, $pk);

        $v = ClienteContenidoPeer::doSelect($criteria, $con);

        return !empty($v) > 0 ? $v[0] : null;
    }

